function save(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem('fab-draw-document',JSON.stringify(doc));$('save-status').textContent=t('Saved on this device','已保存在本机');}catch{$('save-status').textContent=t('Storage full — download your project','存储已满，请下载项目');}},150);}
function commit(next,selection=selected){if(busy){aborter?.abort();busy=false;}undoStack.push(copy(doc));if(undoStack.length>60)undoStack.shift();redoStack=[];doc=validateDocument(next);selected=selection.filter(id=>doc.shapes.some(s=>s.id===id));revision++;pending=null;save();renderAll();}
