function undo(){if(pending){pending=null;renderAll();return;}if(!undoStack.length)return;aborter?.abort();redoStack.push(copy(doc));doc=undoStack.pop();selected=[];revision++;save();renderAll();}
function redo(){if(!redoStack.length||pending)return;aborter?.abort();undoStack.push(copy(doc));doc=redoStack.pop();selected=[];revision++;save();renderAll();}
