 openDialog(t('Edit dimension','编辑尺寸'),`<p>${esc(d.label)} mm · ${t('Other dimensions stay linked to the part.','其他尺寸与零件保持关联。')}</p><label>${t('New value · mm','新数值 · mm')}<input id="dimension-value" type="number" min="0.001" step="any" value="${d.value}"></label><div class="dialog-actions">${btn('dimension-apply',t('Apply','应用'),'check','primary')}</div>`);
