 openDialog(t('Bracket measurements · mm','支架尺寸 · 毫米'),`<p>${t('Keep conflicting printed values in their separate fields. Select which chain to use below. Blank means unknown; no values are inferred.','分别保留图中冲突的尺寸，并选择采用哪一组。空白表示未知，不会自动推测。')}</p><div class="prop-grid">${Object.entries(BRACKET_LABELS).map(([key,label])=>`<label>${esc(label)}<input data-bracket-field="${key}" type="number" min="0.001" step="any" value="${plan[key]??''}"></label>`).join('')}</div><div class="form-stack"><label>${t('Dimension chain to use','采用的尺寸组')}<select id="bracket-basis"><option value="unresolved">${t('Not resolved','未确定')}</option><option value="lower" ${plan.basis==='lower'?'selected':''}>${t('Lower dimensions','下方尺寸')}</option><option value="upper" ${plan.basis==='upper'?'selected':''}>${t('Upper dimensions','上方尺寸')}</option></select></label><label><input id="bracket-top-anchor" type="checkbox" ${plan.topHolesAtArcCentre?'checked':''}>${t('Top holes share the upper arc-centre level','顶部两孔在上方圆弧中心高度')}</label><label><input id="bracket-bottom-anchor" type="checkbox" ${plan.lowerOffsetToArcCentre?'checked':''}>${t('Lower vertical offset ends at bottom arc centre, not bottom edge','下方竖直尺寸止于底部圆弧中心，而非最低边缘')}</label></div><div class="dialog-actions">${btn('save-bracket-readings',t('Check measurements','检查尺寸'),'check','primary')}</div>`);
 $('save-bracket-readings').onclick=()=>{aborter?.abort();const next={...plan,basis:$('bracket-basis').value,topHolesAtArcCentre:$('bracket-top-anchor').checked,lowerOffsetToArcCentre:$('bracket-bottom-anchor').checked};document.querySelectorAll('[data-bracket-field]').forEach(input=>next[input.dataset.bracketField]=input.value===''?null:Number(input.value));photo.measurementPlan=next;photo.confirmed=false;photo.consumed=false;pending=null;revision++;const report=bracketReport(next,language);photoReview=report.canConfirm;messages.push({role:'assistant',content:report.reply});suggestions=report.suggestions;$('dialog').close();renderAll();};
